      "claim_user_summary_scope",
      "claim_large_incumbent_gain",
      "claim_midsized_exporter_vulnerability",
      "claim_ratification_uncertainty"
    ]
  },
  "claims": [
    {
      "claim_id": "claim_user_summary_scope",
