      "kind": "assessment",
      "provenance": "analyst-judgment",
      "basis_claim_ids": [
        "claim_large_vs_sme_compliance"
      ]
    },
    {
      "claim_id": "claim_bilateral_leverage_balance",
      "text": "Regulatory gatekeepers and standards organizations in both jurisdictions gain increased structural leverage as arbiters of technical equivalence.",
      "kind": "assessment",
      "provenance": "inference",
      "basis_claim_ids": [
        "claim_user_summary_scope"
      ]
    },
    {
      "claim_id": "claim_ratification_uncertainty",
      "text": "Draft summary terms remain subject to legislative scrutiny, sector lobby adjustments, and potential political delays before formal ratification.",
      "kind": "assumption",
      "provenance": "analyst-judgment",
      "basis_claim_ids": [
        "claim_user_summary_scope"
